const {chromium}=require('/tmp/devdesk-runtime/node/node_modules/playwright');
const fs=require('fs'),crypto=require('crypto'),assert=require('assert/strict');
const dir='/work/evidence/.devdesk/19fe7521-2a56-3b7a-1f7a-482b09b3e3d1';
const source=fs.readFileSync('/work/index.html');
const baseline=Buffer.from(source.toString().replace(' aria-describedby=\"language-hint\"',''));
const blob=crypto.createHash('sha1').update(Buffer.concat([Buffer.from("'`blob ${baseline.length}'"\\0"'`),baseline])).digest('"'hex');
assert.equal(blob,'c6eaf9f4beb3541998362c73f56fb12168382515');
fs.writeFileSync('/tmp/devdesk-runtime/baseline.html',baseline);
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
(async()=>{let browser;const records=[];try{
 browser=await chromium.launch({executablePath:process.env.DEVDESK_RUNTIME_CACHE+'/browsers/chromium-1208/chrome-linux/chrome',headless:true,timeout:20000,args:['--no-sandbox','--disable-dev-shm-usage','--no-zygote','--renderer-process-limit=1']});
 for(const width of [320,1280]){
 const page=await browser.newPage({viewport:{width,height:720}});page.setDefaultTimeout(10000);
 try{
 const layout=()=>page.locator('body, .language-controls, #language-toggle, main, h1, #welcome-message, #language-hint').evaluateAll(ns=>ns.map(n=>({tag:n.tagName,rect:n.getBoundingClientRect().toJSON(),font:getComputedStyle(n).font})));
 await page.goto('file:///tmp/devdesk-runtime/baseline.html'); await page.evaluate(()=>document.fonts.ready);const before=await layout();await page.screenshot({path:"'`${dir}/recovery-baseline-${width}.png`,fullPage:true});
 await page.goto('"'file:///work/index.html');await page.evaluate(()=>document.fonts.ready);assert.deepEqual(await layout(),before);await page.screenshot({path:"'`${dir}/recovery-updated-${width}.png`,fullPage:true});
 const check=async english=>{
 assert.equal(await page.locator('"'#language-toggle').getAttribute('aria-describedby'),'language-hint');assert.equal(await page.locator('[id=\"language-hint\"]').count(),1);
 for(const [id,text,lang] of [['welcome-message',english?'Welcome':'欢迎',english?'en':'zh'],['language-toggle',english?'中文':'English',english?'zh':'en'],['language-hint',english?'Language switching supports keyboard controls':'语言切换支持键盘操作',english?'en':'zh']]){assert.equal(await page.locator('#'+id).textContent(),text);assert.equal(await page.locator('#'+id).getAttribute('lang'),lang);}
 assert.equal(await page.evaluate(()=>window.originalHint===document.getElementById('language-hint')),true);
 };
 await page.evaluate(()=>window.originalHint=document.getElementById('language-hint'));await check(false);
 await page.locator('#language-toggle').click();await check(true);
 await page.reload();await page.evaluate(()=>window.originalHint=document.getElementById('language-hint'));await check(false);
 await page.keyboard.press('Tab');assert.equal(await page.locator('#language-toggle').evaluate(n=>n===document.activeElement),true);
 await page.keyboard.press('Enter');await check(true);await page.keyboard.press('Space');await check(false);
 for(let i=1;i<=24;i++){await page.locator('#language-toggle').click();await check(i%2===1);}
 await page.reload();await page.evaluate(()=>window.originalHint=document.getElementById('language-hint'));await check(false);
 assert.equal(hash(fs.readFileSync("'`${dir}/recovery-baseline-${width}.png`)),hash(fs.readFileSync(`${dir}/recovery-updated-${width}.png`)));
 records.push({width,layoutEqual:true,screenshotsEqual:true,mouse:true,tab:true,enter:true,space:true,repeatedToggles:24,refreshFromEnglish:true,refreshFromChinese:true});
 }finally{await page.close();}
 }
 console.log(JSON.stringify({source:'"'/work/index.html',sourceRevision:'5a92bd5e6bce20f5d4144221d5f567c1e9cdf69f',sha256:hash(source),baselineBlob:blob,baselineSha256:hash(baseline),browser:browser.version(),records}));
 }finally{if(browser)await browser.close();}})().catch(e=>{console.error(e);process.exitCode=1});
